using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class B4PolishSurvey {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_LayoutPolish/";static string O=>R+"/Docs/Review/2026-11-09_B4_LayoutPolish/";
 static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Status(){var s=SceneManager.GetActiveScene();return new{scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,roots=s.GetRootGameObjects().Select(g=>g.name),selection=Selection.activeGameObject?P(Selection.activeGameObject.transform):""};}
 public static object Baseline(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");if(File.Exists(H+"before.unity"))throw new Exception("Baseline exists");Directory.CreateDirectory(O);bool dirty=s.isDirty;EditorSceneManager.SaveScene(s,H+"before.unity",true);if(dirty)EditorSceneManager.SaveScene(s);
  var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var all=ts.Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,path=P(t),p=V(t.position),e=V(t.eulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}).ToArray();File.WriteAllText(H+"transforms_before.json",JsonConvert.SerializeObject(all,Formatting.Indented));
  var inst=ts.Where(t=>PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)).Select(t=>{var rs=t.GetComponentsInChildren<Renderer>();var b=new Bounds(t.position,Vector3.zero);if(rs.Length>0){b=rs[0].bounds;foreach(var rr in rs.Skip(1))b.Encapsulate(rr.bounds);}return new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,path=P(t),asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject),p=V(t.position),e=V(t.eulerAngles),active=t.gameObject.activeInHierarchy,bc=V(b.center),bs=V(b.size),colliders=t.GetComponentsInChildren<Collider>().Select(c=>new{name=c.name,type=c.GetType().Name,center=V(c.bounds.center),size=V(c.bounds.size)})};}).ToArray();File.WriteAllText(H+"instances_before.json",JsonConvert.SerializeObject(inst,Formatting.Indented));
  File.WriteAllText(H+"lights_before.json",JsonConvert.SerializeObject(ts.Select(t=>t.GetComponent<Light>()).Where(l=>l).Select(l=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(l).ToString(),path=P(l.transform),p=V(l.transform.position),e=V(l.transform.eulerAngles),l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),enabled=l.enabled}),Formatting.Indented));return new{scene=s.path,initiallyDirty=dirty,objects=all.Length,instances=inst.Length};}
 static void Shot(string file,Vector3 p,Vector3 target,float fov=85){var go=new GameObject("Polish_TemporaryCamera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(target);c.useOcclusionCulling=false;c.nearClipPlane=.05f;c.farClipPlane=350;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var previous=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+file+".png",tex.EncodeToPNG());}finally{RenderTexture.active=previous;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Capture(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");Directory.CreateDirectory(O);var plan=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(R+"/SourceAssets/B4_ExperimentOperations/layout.json"));var player=s.GetRootGameObjects().FirstOrDefault(g=>g.name.StartsWith("Player"));bool active=player&&player.activeSelf;if(player)player.SetActive(false);try{foreach(var r in plan["rooms"]){var center=new Vector3((float)r["x"],-66,-(float)r["v"]);var d=r["doors"][0];var dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;Shot("before_"+(string)r["id"],center+dir*((float)r["r"]-1.3f)+Vector3.up*1.7f,center+Vector3.up*1.2f,94);}}finally{if(player)player.SetActive(active);}return new{captured=plan["rooms"].Count()};}
}
